func StripLedger(body string) (string, *Ledger, bool, error) {
	// The genuine block is always the last element of the body
	// (finalizeBody/trackedNoIssuesBody append it after all sections), and
	// only the block's own payload is neutralized against marker injection.
	// Anchor at the last marker so unneutralized summary content cannot
	// relocate the block start.
	i := strings.LastIndex(body, LedgerStartMarker)
	if i < 0 {
		return body, nil, false, nil
	}

